<span class="line"><span style="color:#C678DD;">    var</span><span style="color:#E06C75;"> reading</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> await </span><span style="color:#E5C07B;">sensor</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">ReadAsync</span><span style="color:#ABB2BF;">();</span></span>
